insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('8a947fc1-1eb1-4027-bddb-0972bfcc1c12', 'af058d10-44e6-4abc-a656-875844d67356', null, 0, 'Kuala Lumpur', 'Malaisie', 2, 3.139, 101.6869, 'Train Lille → Paris le 07/10 (74 € pour 2, payé), puis vol Etihad Paris → Kuala Lumpur, départ 21h25, arrivée le 08/10 à 19h45 (602 € pour 2, payé).', 'Nuit du 07 en avion. Upper Suites KL Sentral, 1 nuit du 08 au 09/10 : 25 € pour 2, payé (annulable avant le 07/10).', 350.5, 350.5, 'PAYE', 'PAYE', '[]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('74a6516b-db86-4e28-828c-720253dc7106', 'af058d10-44e6-4abc-a656-875844d67356', null, 1, 'Cemoro Lawang', 'Indonésie', 1, -7.9420691, 112.9529769, 'Vol AirAsia Kuala Lumpur → Surabaya, 09h10 → 10h45 (184,75 € pour 2, payé ; option bagage cabine XTRA à acheter, 7 kg de base). Puis voiture privée Surabaya → Cemoro Lawang avec escale à la cascade de Madakaripura, ≈ 6h (≈ 65 € pour 2, fourchette 45 à 65 €, à réserver). Bien préciser l’arrêt et le dépôt à Cemoro Lawang.', 'Pesona Bromo Homestay, 1 nuit : 34 € pour 2, réservé (prélèvement le 06/10). Autres options vues : Cellino Homestay, Homestay Lereng Bromo.', 141.88, 92.38, 'RESERVE', 'A_RESERVER', '[{"id": "5b5a126d", "title": "Cascade de Madakaripura", "place": "Madakaripura, Java", "notes": "Escale sur la route, 1h30 à 2h sur place, guide local obligatoire.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "6b5ac6cb", "title": "Coucher de soleil à Bukit Mentigen", "place": "Bukit Mentigen, Cemoro Lawang", "notes": "Vers 16h30, 20 min à pied depuis le village.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('090d4c70-1c36-4296-9469-213230ab093f', 'af058d10-44e6-4abc-a656-875844d67356', null, 2, 'Tumpak Sewu (Pronojiwo)', 'Indonésie', 2, -8.2311, 112.9175, 'Jeep privée (voiture 4x4) Cemoro Lawang → Pronojiwo par la mer de sable, la savane de Jemplang, 10h30 → 13h30 (≈ 85 € pour 2, fourchette 70 à 85 €, à réserver). Confirmer la veille au soir, régler à l’arrivée.', 'Sambas Cottages (piscine), 2 nuits du 10 au 12/10 : 37 € pour 2, réservé (prélèvement le 08/10). Alternative vue : Indah Damai Cottages, 49 €.', 61.0, 0.0, 'RESERVE', 'A_RESERVER', '[{"id": "16e32310", "title": "Lever du soleil sur le Bromo + cratère", "place": "King Kong Hill / Seruni Point, Bromo", "notes": "Entrée du parc national : 320 000 IDR/pers, tarif week-end (le 10/10 est un samedi).", "estimatedPrice": 18.0, "price": 0.0, "lat": null, "lng": null}, {"id": "0815514a", "title": "Descente de Tumpak Sewu + Goa Tetes", "place": "Tumpak Sewu, Pronojiwo", "notes": "Partir très tôt, échelles en bambou et ponts de corde.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "b575ce76", "title": "Scooter + cascades Kapas Biru / Coban Sriti", "place": "Pronojiwo", "notes": "Après-midi du 11/10, scooter et entrées.", "estimatedPrice": 15.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('455bc01b-77e6-408e-811e-b3e81350d4fb', 'af058d10-44e6-4abc-a656-875844d67356', null, 3, 'Surabaya', 'Indonésie', 1, -7.3797, 112.787, 'Voiture Pronojiwo → gare de Klakah, 1h15 (≈ 20 € pour 2, à réserver, prévoir 30 min de marge sur la route des lahars), puis train Klakah (KK) → Surabaya Gubeng (SGU), 2h30 (≈ 10 € pour 2, à réserver dès l’ouverture des ventes H-45 sur KAI Access ou tiket.com).', 'Cordia Hotel Surabaya Airport, 1 nuit : 27 € pour 2, réservé (prélèvement à venir).', 28.5, 0.0, 'RESERVE', 'A_RESERVER', '[{"id": "8da8a2f7", "title": "Panorama de Pos Satpol PP / Simbar Semeru", "place": "Pronojiwo", "notes": "06h00-08h30 en scooter, avant le départ : rivières de lave noire et le Semeru qui fume.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('6e647938-d661-4e0a-8113-7d4e23b592ee', 'af058d10-44e6-4abc-a656-875844d67356', null, 4, 'Labuan Bajo', 'Indonésie', 1, -8.4964, 119.8877, 'Vol Citilink Surabaya → Denpasar, 05h30 → 07h35 (99,68 € pour 2, payé, via Traveloka), puis vol AirAsia Denpasar → Labuan Bajo, 09h00 → 10h10 (146,47 € pour 2, payé). Correspondance de 1h25 sur billets séparés.', 'Hôtel à choisir, ≈ 35 € pour 2. Options : Komodo Lodge 33 €, World BnB 33 €, Pavilla Labuan Bajo 36 €, Escape Bajo 41 €.', 140.58, 123.08, 'A_RESERVER', 'PAYE', '[]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('79c0e595-fc42-4e25-bc93-7f7a78929740', 'af058d10-44e6-4abc-a656-875844d67356', null, 5, 'Croisière plongée Komodo', 'Indonésie', 4, -8.55, 119.49, 'Liveaboard (bateau de plongée) 4 jours / 3 nuits dans le parc national de Komodo, au départ de Labuan Bajo.', 'À bord. 685 €/pers × 2 + taxe parc 107 € + équipement 150 € = 1 626 € pour 2. Acompte de 809,56 € déjà versé, solde ≈ 816 € (à confirmer : acompte ou devis concurrent ?).', 813.0, 404.78, 'RESERVE', 'RESERVE', '[{"id": "91b57962", "title": "Plongées dans le parc national de Komodo", "place": "Parc national de Komodo", "notes": "Inclus dans le prix du liveaboard.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "8b5ea6a9", "title": "Pourboires de l’équipage", "place": "Liveaboard", "notes": "Usage : 5 à 10 % du prix de la croisière (120 € pour 2).", "estimatedPrice": 60.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('7a10e4d3-555b-413c-a651-f40cefb931d1', 'af058d10-44e6-4abc-a656-875844d67356', null, 6, 'Labuan Bajo', 'Indonésie', 1, -8.4964, 119.8877, 'Retour du bateau à Labuan Bajo. Pas de plongée ce jour-là : vol le lendemain.', 'Nuit à Labuan Bajo ≈ 70 € pour 2, à réserver.', 35.0, 0.0, 'A_RESERVER', 'RESERVE', '[{"id": "1dd104e6", "title": "Location scooter", "place": "Labuan Bajo", "notes": "1 jour.", "estimatedPrice": 5.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('f82d962a-e182-4277-81a0-d715e344f973', 'af058d10-44e6-4abc-a656-875844d67356', null, 7, 'Tetebatu', 'Indonésie', 2, -8.5530753, 116.4194112, 'Vol Labuan Bajo → Lombok (LOP), 09h20 → 10h40 (200 € pour 2, payé), puis voiture aéroport → Tetebatu par Kopang et Kotaraja, 1h15 (29 € pour 2 via 12GO Asia, à réserver).', '2 nuits du 19 au 21/10, ≈ 42 € pour 2 (Forest Side Bungalow ; alternative Sarang Walet Homestay 31 €). À réserver.', 135.5, 100.0, 'A_RESERVER', 'A_RESERVER', '[{"id": "f4091d82", "title": "Location de 2 scooters (19 → 22/10)", "place": "Tetebatu", "notes": "5 €/jour par scooter, 4 jours (40 € pour 2).", "estimatedPrice": 20.0, "price": 0.0, "lat": null, "lng": null}, {"id": "ef564819", "title": "Cascades Benang Stokel et Benang Kelambu", "place": "Aik Berik, Lombok", "notes": "Boucle scooter à la journée (1h à 1h15). Guide à l’entrée. Route glissante après la pluie : y aller le matin.", "estimatedPrice": 5.0, "price": 0.0, "lat": null, "lng": null}, {"id": "fb85ef73", "title": "Monkey Forest de Tetebatu", "place": "Tetebatu", "notes": "Sur la route de Kotaraja. Ne rien laisser en main.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "af87fc5d", "title": "Village sasak de Sade", "place": "Sade, Lombok", "notes": "Optionnel, à 20 min de l’aéroport : touristique, halte de 45 min.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('fd05e660-0c5e-49e4-b34e-8b482465cef8', 'af058d10-44e6-4abc-a656-875844d67356', null, 8, 'Sembalun (Bukit Pergasingan)', 'Indonésie', 1, -8.358, 116.531, 'Scooter Tetebatu → Sembalun par le versant est, 2h à 2h30, halte café à Sapit. Partir le matin (averses l’après-midi). Laisser les gros sacs à la guesthouse de Tetebatu.', 'Bivouac au sommet du Bukit Pergasingan (1 808 m), tente fournie par destination.lombok (inclus dans le trek).', 0.0, 0.0, 'A_RESERVER', 'RESERVE', '[{"id": "10943baa", "title": "Trek Bukit Pergasingan (2J/1N)", "place": "Bukit Pergasingan, Sembalun", "notes": "ESTIMATION, devis à demander à destination.lombok : guide, porteur, tente, repas. La feuille indique 110 € en prix mais 160 € en reste, à vérifier. Préciser départ ET retour à Sembalun, et demander où dorment les scooters.", "estimatedPrice": 55.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('769d3c88-08cc-4555-a4a3-173d031bca90', 'af058d10-44e6-4abc-a656-875844d67356', null, 9, 'Tetebatu', 'Indonésie', 1, -8.5530753, 116.4194112, 'Descente au petit matin puis retour en scooter Sembalun → Tetebatu, 2h à 2h30. Arrivée en début d’après-midi.', '1 nuit du 22 au 23/10, ≈ 21 € pour 2 (Sarang Walet Homestay relevé à 15 €). À réserver séparément des 2 premières nuits.', 10.5, 0.0, 'A_RESERVER', 'RESERVE', '[]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('c8dd3f51-0da2-48d5-9960-19718f07cf02', 'af058d10-44e6-4abc-a656-875844d67356', null, 10, 'Kuta Lombok', 'Indonésie', 3, -8.8925, 116.2775, 'Voiture Tetebatu → Kuta Lombok, 1h30 à 2h (33 € pour 2, à réserver). Les scooters sont rendus à Tetebatu, on en reloue à Kuta.', '3 nuits du 23 au 26/10, ≈ 56 € pour 2 (My Beach House Areguling). Alternatives : Cewin’s Homestay 57 €, Zen Village 86 €, Ra Cottage 87 €, Segare Anak Bungalows 134 €. À réserver.', 44.5, 0.0, 'A_RESERVER', 'A_RESERVER', '[{"id": "f9b09c76", "title": "Location de 2 scooters (23 → 25/10)", "place": "Kuta Lombok", "notes": "Casque systématique : contrôles de police fréquents.", "estimatedPrice": 20.0, "price": 0.0, "lat": null, "lng": null}, {"id": "791fc980", "title": "Côté est : Tanjung Aan, Pantai Seger, Bukit Merese", "place": "Kuta Lombok", "notes": "Coucher de soleil à Merese (parking payant, 15 min de montée). Courants à Tanjung Aan, peu de surveillance.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "08ab492e", "title": "Côté ouest : Selong Belanak, Mawun, Mawi (surf débutant)", "place": "Selong Belanak, Lombok", "notes": "Selong Belanak : la meilleure plage pour un premier cours de surf.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "ad7496a3", "title": "Pointe sud-est : baie d’Ekas, Kaliantan, Pink Beach, Tanjung Ringgit", "place": "Ekas, Lombok", "notes": "Journée complète, très peu de monde. Faire le plein de cash avant : très peu de DAB.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('61ef5b88-39e2-4d4a-be0d-6eda028f62fa', 'af058d10-44e6-4abc-a656-875844d67356', null, 11, 'Hanoï', 'Vietnam', 2, 21.0341, 105.85, 'Vol Lombok → Denpasar le matin du 26/10 (≈ 90 € pour 2, compagnie et horaire à confirmer, à réserver), puis vol VietJet Denpasar → Hanoï, ≈ 5h05, arrivée 21h (120 €, payé, rien que pour toi). Grab depuis Noi Bai, 45 min jusqu’au vieux quartier.', 'Nuit du 26 : seul, hébergement à trouver (≈ 25 €). Nuit du 27 : Dong Xuan Boutique, 49 € pour 2 avec petit-déjeuner (retenu, à réserver).', 214.5, 120.0, 'A_RESERVER', 'A_RESERVER', '[{"id": "31ba3021", "title": "Lac Hoan Kiem et première bia hơi", "place": "Vieux quartier, Hanoï", "notes": "Après l’arrivée de Mathéo (27/10 à 14h, au vieux quartier vers 15h30).", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}, {"id": "2514495c", "title": "Vieux quartier, Train Street, food tour", "place": "Hanoï", "notes": "Journée pleine du 28/10. Laisser les gros sacs à l’hôtel pour la boucle.", "estimatedPrice": 0.0, "price": 0.0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('589f29ac-375f-4cac-90a7-cc7bc96c7ff6', 'af058d10-44e6-4abc-a656-875844d67356', null, 12, 'Bus de nuit → Ha Giang', 'Vietnam', 1, 22.8233, 104.9836, 'Marche jusqu’au bus (22 min), puis sleeper bus de nuit Hanoï → Ha Giang vers 21h, 6 à 8h (17 €/pers, à réserver : https://12go.asia/fr/checkout/ae47642e).', 'Nuit dans le bus. Arrivée à Ha Giang vers 5h.', 17.0, 0.0, 'A_RESERVER', 'A_RESERVER', '[]'::jsonb, '[]'::jsonb);
insert into steps (id, trip_id, parent_id, position, city, country, duration, lat, lng, transport_info, lodging_info, budget_estimated, budget_spent, lodging_status, transport_status, activities, checklist) values ('5cdcc46a-2617-4ed4-b96f-da9d8d2171f1', 'af058d10-44e6-4abc-a656-875844d67356', null, 13, 'Boucles Ha Giang + Cao Bang', 'Vietnam', 7, 22.8233, 104.9836, 'Easy rider (moto avec chauffeur) : combiné Ha Giang + Cao Bang de Lila Inn, 7 jours / 6 nuits (https://lilainn.tours/tour/ha-giang-loop-cao-bang-5-day/).', 'Homestays inclus dans le tour, repas inclus. Chambre privée possible : 780 € pour 2, soit 390 €/pers au lieu de 367 €.', 367.0, 0.0, 'A_RESERVER', 'A_RESERVER', '[]'::jsonb, '[]'::jsonb);
