insert into step_notes (step_id, author_name, content, created_at) values ('8a947fc1-1eb1-4027-bddb-0972bfcc1c12', 'Google Sheet', 'Avant le départ : remplir la MDAC (Malaisie) et l’e-VOA (Indonésie).', now() + interval '1 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('74a6516b-db86-4e28-828c-720253dc7106', 'Google Sheet', 'Madakaripura se trouve dans le district de Lumbang/Sukapura, au pied de la montagne qui monte vers Cemoro Lawang. Demander au chauffeur au départ de Surabaya de faire une escale à Madakaripura : 1h30 à 2h sur place avec le guide local obligatoire, puis les 45 dernières minutes de route jusqu’à Cemoro Lawang.', now() + interval '2 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('74a6516b-db86-4e28-828c-720253dc7106', 'Google Sheet', 'Arrivée au village vers 14h-15h. Il fait frais (12-15 °C l’après-midi, près de 5 °C la nuit) : Soto Ayam ou thé chaud dans un warung. Vers 16h30, coucher de soleil à Bukit Mentigen (20 min à pied) sur la mer de nuages. Dîner vers 19h et au lit tôt : réveil vers 02h30-03h00.', now() + interval '3 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('090d4c70-1c36-4296-9469-213230ab093f', 'Google Sheet', '03h00 : départ à pied vers King Kong Hill ou Seruni Point (frontales, vêtements chauds), 1h30 à 2h de montée. 05h15-06h15 : lever de soleil. 06h30-08h30 : descente vers la mer de sable et ascension des 250 marches du cratère. 09h00 : retour à Cemoro Lawang, petit-déjeuner, douche, sacs. 10h30 : Jeep jusqu’à Pronojiwo.', now() + interval '4 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('090d4c70-1c36-4296-9469-213230ab093f', 'Google Sheet', 'Après-midi d’arrivée : vers 15h, belvédère supérieur (Panorama Point) de Tumpak Sewu. Si énergie : scooter à l’homestay (≈ 3 €) pour le point de vue de Kapas Biru (15 min).', now() + interval '5 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('090d4c70-1c36-4296-9469-213230ab093f', 'Google Sheet', 'J4 matin (06h30-11h00) : grande descente de Tumpak Sewu au fond du canyon, puis grotte et cascades de Goa Tetes. Après-midi (14h-17h) : scooter vers Kapas Biru (30 min de descente dans les rizières) ou Coban Sriti (plus sauvage).', now() + interval '6 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('f82d962a-e182-4277-81a0-d715e344f973', 'Google Sheet', 'Atterrissage à LOP à 10h40, ≈ 1h15 de route jusqu’à Tetebatu par Kopang et Kotaraja. Le village sasak de Sade est sur la route (20 min de l’aéroport). Après-midi libre dans les rizières : le sentier part derrière la plupart des guesthouses.', now() + interval '7 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('f82d962a-e182-4277-81a0-d715e344f973', 'Google Sheet', 'J13 : boucle scooter vers Aik Berik, 1h à 1h15 à l’ouest de Tetebatu, sur le versant sud du Rinjani. Benang Kelambu tombe en rideaux à travers la végétation, Benang Stokel est plus classique. Au retour, la Monkey Forest est sur la route de Kotaraja.', now() + interval '8 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('fd05e660-0c5e-49e4-b34e-8b482465cef8', 'Google Sheet', '2h à 2h30 de scooter par le versant est, avec des lacets et du dénivelé. Fin octobre les averses tombent l’après-midi. Halte café à Sapit, village calme vers 800 m avec vue sur le détroit et Sumbawa. Ne monter qu’avec le nécessaire de trek.', now() + interval '9 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('c8dd3f51-0da2-48d5-9960-19718f07cf02', 'Google Sheet', 'Est : Tanjung Aan (sable poivre et sel) et Pantai Seger, coucher de soleil à Bukit Merese. Ouest : Selong Belanak, puis Mawun et Mawi plus sauvages. Sud-est, une journée complète : baie d’Ekas, Pantai Kaliantan, Pink Beach de Tangsi et Tanjung Ringgit. Baignade prudente à Tanjung Aan et Mawun.', now() + interval '10 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('61ef5b88-39e2-4d4a-be0d-6eda028f62fa', 'Google Sheet', '26/10 : tu arrives seul à 21h. 27/10 : Mathéo arrive à 14h. 28/10 : journée pleine à Hanoï puis bus de nuit vers 21h.', now() + interval '11 seconds');
insert into step_notes (step_id, author_name, content, created_at) values ('5cdcc46a-2617-4ed4-b96f-da9d8d2171f1', 'Google Sheet', 'Champs de sarrasin en pleine floraison fin octobre. Ban Gioc a encore un gros débit début novembre, juste après la saison humide.', now() + interval '12 seconds');
insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'repas', 'Nourriture et boissons, Indonésie (16 €/jour × 20 jours)', 320, 'a_payer', 'Montant de la feuille Indonésie, ramené à 1 personne.');
