insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'transport', 'Essence, parkings, divers scooter (Indonésie)', 30, 'a_payer', '');
insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'activites', 'Guides cascades (Madakaripura, Benang Stokel…)', 20, 'a_payer', 'Guide local obligatoire sur plusieurs sites.');
insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'visa', 'Visa Vietnam', 0, 'a_payer', 'A priori pas de visa : exemption de 45 jours pour les Français, et tu restes du 26/10 au 29/11 (34 jours). À vérifier avant le départ.');
insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'repas', 'Repas et extras, Vietnam partie 1 (hors boucle)', 200, 'a_payer', '25 €/jour, les repas sont inclus pendant la boucle.');
insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'repas', 'Repas, jours libres du 10 au 13/11', 60, 'a_payer', 'Estimation : 20 €/jour.');
