insert into preparation_items (trip_id, category, title, amount, payment, notes) values ('af058d10-44e6-4abc-a656-875844d67356', 'repas', 'Pourboires et imprévus, Vietnam partie 2', 50, 'a_payer', '150 € pour 3.');
